bs-toggle="collapse" data-bs-target="#edit-risk-<?= (int)$risk->id ?>">แก้ไข</button><?= Html::a('ลบ',['delete-risk','id'=>$risk->id],['class'=>'btn btn-sm btn-outline-danger','data-method'=>'post','data-confirm'=>'ลบความเสี่ยงนี้?']) ?></div><div class="collapse mt-3" id="edit-risk-<?= (int)$risk->id ?>"><div class="bg-body-tertiary border rounded-3 p-3"><?= $this->render('_risk_form',['step'=>$step,'risk'=>$risk]) ?></div></div><?php endif; ?></section><?php endforeach; ?><?php if(!$step->risks): ?><div class="small text-body-secondary">ขั้นตอนนี้ยังไม่มีความเสี่ยง และจะยังคงแสดงใน Flow chart</div><?php endif; ?></div></article><?php endforeach; ?><?php if(!$model->steps): ?><div class="list-group-item bg-body text-center py-5 text-body-secondary">ยังไม่มีขั้นตอนการปฏิบัติงาน</div><?php endif; ?></div></section>
