$riskError=(string)Yii::$app->request->get('risk_error_id','');$openStep=(int)Yii::$app->request->get('open_step_id',0);
$this->registerJs(<<<JS
document.querySelectorAll('.csa-risk-form').forEach(function(form){var select=form.querySelector('.js-adequacy');function sync(){var required=select&&select.value==='inadequate';form.querySelectorAll('.js-plan-required').forEach(function(field){field.required=required;});var residual=form.querySelector('.js-residual-risk');if(residual)residual.required=required;}select?.addEventListener('change',sync);sync();});
JS);
